const CACHE='stamattina-v8';
const base=new URL('./',self.location).pathname;
const shell=['','index.html','style.css?v=8','app.js?v=8','data/current.json','manifest.webmanifest','assets/icon.svg','assets/icon-192.png','assets/icon-512.png'];
self.addEventListener('install',e=>e.waitUntil((async()=>{const c=await caches.open(CACHE);await c.addAll(shell.map(x=>new Request(base+x,{cache:'reload'})));const edition=await (await c.match(base+'data/current.json')).json();await Promise.allSettled(edition.articles.filter(a=>a.image).map(async a=>{const r=await fetch(new URL(a.image.src,self.location.origin+base),{mode:'cors'});if(r.ok)await c.put(new URL(a.image.src,self.location.origin+base),r)}));await self.skipWaiting()})()));
self.addEventListener('activate',e=>e.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('stamattina-')&&k!==CACHE).map(k=>caches.delete(k)))),self.clients.claim()])));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET')return;const origin=new URL(e.request.url).origin;if(origin!==self.location.origin&&origin!=='https://upload.wikimedia.org')return;e.respondWith((async()=>{const cache=await caches.open(CACHE);try{const r=await fetch(e.request,origin===self.location.origin?{cache:'no-store'}:{});if(r.ok)await cache.put(e.request,r.clone());return r}catch{const old=await cache.match(e.request);if(old){if(new URL(e.request.url).pathname===base+'data/current.json'){const headers=new Headers(old.headers);headers.set('X-Stamattina-Cache','offline');return new Response(old.body,{status:old.status,headers})}return old;}if(e.request.mode==='navigate')return await cache.match(base+'index.html');return new Response('Offline',{status:503})}})())});
